changeSet.sql:
UPDATE "${schema}".attendance SET status = 'COMPLETE', updated_at = NOW() WHERE status = 'OPEN' AND check_out_time IS NOT NULL;
WITH duplicate_open AS ( SELECT id, ROW_NUMBER() OVER ( PARTITION BY tenant_id, employee_id ORDER BY created_at DESC, id DESC ) AS open_rank FROM "${schema}".attendance WHERE status = 'OPEN' AND check_out_time IS NULL ) UPDATE "${schema}".attendance AS attendance SET status = 'INCOMPLETE', updated_at = NOW() FROM duplicate_open WHERE attendance.id = duplicate_open.id AND duplicate_open.open_rank > 1;
CREATE UNIQUE INDEX uq_attendance_one_open ON "${schema}".attendance (tenant_id, employee_id) WHERE check_out_at IS NULL AND status = 'OPEN';
ALTER TABLE "${schema}".attendance ADD CONSTRAINT ck_attendance_completed_instants CHECK ( (check_in_at IS NULL AND check_out_at IS NULL) OR ( check_in_at IS NOT NULL AND ( (status IN ('OPEN', 'INCOMPLETE') AND check_out_at IS NULL) OR ( COALESCE(status, 'COMPLETE') NOT IN ('OPEN', 'INCOMPLETE') AND check_out_at IS NOT NULL AND check_out_at > check_in_at ) ) ) );
